def refs():
    return [{**s, "subject": "math", "locator": "尺規作圖、垂直平分線、角平分線、等距軌跡、複製角、圓弧交點與圓心連線", "observedPattern": "公開數學評量常要求判斷尺規作圖的操作順序與圓規保距作用，並把作圖結果連結到垂直平分線、角平分線及兩圓交點的幾何性質；本題只取能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-math-performance-s-iv-13-{n}", "subject": "math", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三份公立學校／公開會考數學試題僅供尺規作圖、等距軌跡與圓幾何能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開數學試題的尺規作圖方向獨立改寫；題幹、數值、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "用尺規作圖作線段 AB 的垂直平分線時，以 A、B 為圓心的圓弧半徑應如何選？", {"A": "小於 AB 的一半", "B": "恰好等於 AB 的一半", "C": "大於 AB 的一半且兩圓弧能相交", "D": "一定要等於 AB"}, "C", "要讓以 A、B 為圓心的兩弧在上、下方相交，半徑須大於 AB 的一半；交點連線才可作垂直平分線，選 C。", "不是只看半徑大小，而是確認兩圓弧能形成兩個交點。", ["兩圓弧半徑要相同。", "若半徑小於或等於 AB/2，弧可能無法產生兩個交點。", "選半徑大於 AB/2。", "使兩弧在 AB 兩側相交。", "連結兩交點即可得到垂直平分線，所以選 C。"], "medium"),
    make(2, "角平分線上的任一點，到角的兩邊距離有何關係？", {"A": "一定相差一倍", "B": "相等", "C": "只與角度大小相等", "D": "無法比較"}, "B", "角平分線上的點到角的兩邊距離相等，這是角平分線的等距性質，選 B。", "把點向兩邊作垂線，將角平分線定理轉成兩段垂距比較。", ["取角平分線上的點 P。", "從 P 向兩邊作垂線得到兩段距離。", "角平分線兩側對稱。", "兩段垂距相等。", "所以選 B。"], "easy"),
    make(3, "用尺規作出線段 AB 的垂直平分線後，兩個圓弧交點的連線與 AB 的夾角為何？", {"A": "30°", "B": "60°", "C": "90°", "D": "180°"}, "C", "兩交點都到 A、B 等距，連線是 AB 的垂直平分線，因此與 AB 垂直，夾角為 90°，選 C。", "先用等距判斷作圖線是垂直平分線，再讀取垂直角。", ["兩個圓弧交點分別到 A、B 等距。", "連接兩交點形成等距點軌跡。", "等距點軌跡是 AB 的垂直平分線。", "垂直平分線與 AB 互相垂直。", "所以夾角為 90°，選 C。"], "easy"),
    make(4, "若平面上一點 P 到 A、B 兩點的距離相等，P 必在何處？", {"A": "AB 的中線上", "B": "AB 的垂直平分線上", "C": "AB 的平行線上", "D": "以 A 為圓心的任意圓上"}, "B", "到 A、B 等距的所有點組成 AB 的垂直平分線，因此 P 在其上，選 B。", "把『到兩定點等距』辨識為垂直平分線的軌跡。", ["寫出條件 PA=PB。", "找出具有此等距性質的點集合。", "該集合是 AB 的垂直平分線。", "因此 P 必位於該直線上。", "所以選 B。"], "easy"),
    make(5, "用尺規作一個與已知角 ∠A 相等的角時，先以 A 為圓心在原角兩邊畫弧，通常是為了記錄什麼？", {"A": "角的兩邊長度", "B": "角的兩邊與弧的交點間距離", "C": "三角形面積", "D": "圓心位置"}, "B", "同一圓弧會在原角兩邊留下兩個交點，這兩交點間的弦長用來在新角中複製，選 B。", "理解複製角是先複製弧，再複製兩交點間的距離。", ["以原角頂點為圓心畫固定半徑弧。", "弧與兩邊交於兩點。", "固定圓規開口量取兩交點間距離。", "在新角弧上截出相同弦長。", "因此記錄的是兩交點間距離，選 B。"], "medium"),
    make(6, "兩圓相交於 A、B 兩點，兩圓心的連線具有什麼性質？", {"A": "通過 A、B 的中點且垂直 AB", "B": "平行於 AB", "C": "一定通過 A", "D": "一定等於 AB"}, "A", "A、B 是兩圓共同弦的端點；兩圓心到 A、B 分別等距，因此兩圓心連線是 AB 的垂直平分線，選 A。", "把共同弦端點的等距條件套到兩個圓心。", ["同一圓的半徑到 A、B 相等。", "兩個圓心都到 A、B 等距。", "兩個等距點決定 AB 的垂直平分線。", "所以兩圓心連線垂直 AB 且通過其中點。", "選 A。"], "medium"),
    make(7, "三角形三邊的垂直平分線會交於哪一點？", {"A": "內心", "B": "重心", "C": "外心", "D": "垂心"}, "C", "三邊垂直平分線交點到三個頂點等距，是三角形外心，選 C。", "把作圖線的名稱與三角形四心的定義配對。", ["確認每條線是邊的垂直平分線。", "交點到各邊端點等距。", "因此可作三頂點的外接圓。", "圓心就是外心。", "所以選 C。"], "easy"),
    make(8, "三角形三個角的角平分線會交於哪一點？", {"A": "外心", "B": "內心", "C": "重心", "D": "垂心"}, "B", "三個內角角平分線的交點到三邊等距，稱為內心，選 B。", "從『內角角平分線』辨認內心，而非外心的垂直平分線。", ["確認線段平分的是三個內角。", "三線會在三角形內部共點。", "共點到三邊距離相等。", "這個共點稱為內心。", "所以選 B。"], "easy"),
    make(9, "若以線段 CD 的兩端為圓心，畫出半徑相等且互相交於 P、Q 的兩段圓弧，則 PQ 與 CD 的關係為何？", {"A": "平行", "B": "垂直平分", "C": "重合", "D": "無法判定"}, "B", "P、Q 都到 C、D 等距，因此 P、Q 位於 CD 的垂直平分線上；PQ 就是該垂直平分線，選 B。", "將兩個圓弧交點視為 CD 的等距點，再套用軌跡定理。", ["由相等半徑得 PC=PD、QC=QD。", "P、Q 都是到 C、D 等距的點。", "等距點集合是 CD 的垂直平分線。", "連結 P、Q 得到該直線。", "所以 PQ 垂直且平分 CD，選 B。"], "medium"),
    make(10, "下列哪一項最能說明尺規作圖中的圓規作用？", {"A": "只能畫出直線", "B": "複製或比較固定長度", "C": "直接測量角度數", "D": "把曲線變成直角"}, "B", "圓規可保持開口長度，用來畫等半徑圓弧、截取線段與複製距離，選 B。", "把圓規的幾何功能歸納為保距，而非量角或畫直線。", ["圓規兩腳開口代表一段固定距離。", "移動圓規仍能保留這段長度。", "可用等半徑弧或截取線段複製距離。", "直尺負責畫直線，圓規不直接量角。", "所以選 B。"], "easy"),
]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
